	VariableSampledMeasurands = "SampledMeasurands"
	// VariableSamplingInterval is the standardized variable SamplingInterval. The sampling interval in
	// *seconds*.
	VariableSamplingInterval = "SamplingInterval"
	// VariableSeccId is the standardized variable SeccId. The name of the SECC in the string format as
