	VariableTimeout = "Timeout"
	// VariableToken is the standardized variable Token. String of bytes representing an ID token.
	VariableToken = "Token"
	// VariableTokenType is the standardized variable TokenType. Type of Token.
	VariableTokenType = "TokenType"
	// VariableTotalCostFallbackMessage is the standardized variable TotalCostFallbackMessage. Message
