	VariableTotalCostFallbackMessage = "TotalCostFallbackMessage"
	// VariableTries is the standardized variable Tries. Number of attempts done by a Component.
	VariableTries = "Tries"
	// VariableTripped is the standardized variable Tripped. Single-shot device requires explicit
