	VariableTxStartPoint = "TxStartPoint"
	// VariableTxStartedMeasurands is the standardized variable TxStartedMeasurands. Sampled measurands
	// to be included in the _meterValues_ element of TransactionEventRequest(Started).
	VariableTxStartedMeasurands = "TxStartedMeasurands"
	// VariableTxStopPoint is the standardized variable TxStopPoint. Stop points of a transaction.
	VariableTxStopPoint = "TxStopPoint"
	// VariableTxUpdatedInterval is the standardized variable TxUpdatedInterval. Interval between
